import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"L1 guide: watchdog and health","description":"","frontmatter":{},"headers":[],"relativePath":"l1/watchdog-health.md","filePath":"l1/watchdog-health.md"}'),l={name:"l1/watchdog-health.md"};function o(h,e,d,c,r,i){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="l1-guide-watchdog-and-health" tabindex="-1">L1 guide: watchdog and health <a class="header-anchor" href="#l1-guide-watchdog-and-health" aria-label="Permalink to &quot;L1 guide: watchdog and health&quot;">​</a></h1><h2 id="watchdog-kernel-core-core-watchdog-h-18-declarations-numbered-5" tabindex="-1">Watchdog - <code>kernel/core/core_watchdog.h</code> (18 declarations; numbered 5) <a class="header-anchor" href="#watchdog-kernel-core-core-watchdog-h-18-declarations-numbered-5" aria-label="Permalink to &quot;Watchdog - \`kernel/core/core_watchdog.h\` (18 declarations; numbered 5)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watchdog_register(name, timeout_ms, policy)  -&gt; slot</span></span>
<span class="line"><span>watchdog_start(slot)</span></span>
<span class="line"><span>watchdog_feed(slot)</span></span>
<span class="line"><span>watchdog_stop(slot)</span></span>
<span class="line"><span>watchdog_set_timeout(slot, ms)</span></span></code></pre></div><p>A registered slot is a <em>policy</em> watchdog: the task must feed it; timeout kills the task (reason logged) while the kernel lives. Hardware watchdogs (Intel TCO, ACPI WDAT) are layered underneath and reset the whole machine - the E2E suite proves both with real resets and second boots.</p><h2 id="health-kernel-core-core-health-h-8-declarations-numbered-5" tabindex="-1">Health - <code>kernel/core/core_health.h</code> (8 declarations; numbered 5) <a class="header-anchor" href="#health-kernel-core-core-health-h-8-declarations-numbered-5" aria-label="Permalink to &quot;Health - \`kernel/core/core_health.h\` (8 declarations; numbered 5)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>health_get_cpu(out)</span></span>
<span class="line"><span>health_get_mem(out)</span></span>
<span class="line"><span>health_get_tasks(out)</span></span>
<span class="line"><span>health_get_io(out)</span></span>
<span class="line"><span>health_export(path)          // valid JSON to /var/log/health.json</span></span></code></pre></div><p>Thresholds raise alarms into the kernel log (<code>CPU-LOCKED</code> on a pinned core...); <code>health</code>, <code>health watch</code>, <code>health export</code> are the commands; the E2E asserts the alarm lines and JSON validity.</p><h2 id="klog-kernel-lib-lib-klog-h-29-declarations-numbered-6" tabindex="-1">klog - <code>kernel/lib/lib_klog.h</code> (29 declarations; numbered 6) <a class="header-anchor" href="#klog-kernel-lib-lib-klog-h-29-declarations-numbered-6" aria-label="Permalink to &quot;klog - \`kernel/lib/lib_klog.h\` (29 declarations; numbered 6)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>klog_write(level, fmt, ...)</span></span>
<span class="line"><span>klog_set_level(lvl)</span></span>
<span class="line"><span>klog_set_level_enabled(lvl, on)</span></span>
<span class="line"><span>klog_flush()</span></span>
<span class="line"><span>klog_rotate()</span></span>
<span class="line"><span>klog_filter_set(min_level)</span></span></code></pre></div><p>Levels: DEBUG/INFO/WARN/ERROR/FATAL; rotation (<code>kernel.log</code> -&gt; <code>kernel.log.1</code>, threshold 4096) and filtering are real, E2E-verified behaviours.</p>`,10)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
